(function(){'use strict';const KEY='safariPocketbookTrip',empty=document.getElementById('tripEmpty'),content=document.getElementById('tripContent');if(!empty||!content)return;const esc=value=>String(value||'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));const read=()=>{try{const value=JSON.parse(localStorage.getItem(KEY)||'null');return value&&Array.isArray(value.stops)&&Array.isArray(value.countries)?value:null}catch(error){return null}};const write=value=>localStorage.setItem(KEY,JSON.stringify(value));function toast(message){const node=document.getElementById('toast');node.textContent=message;node.classList.add('show');setTimeout(()=>node.classList.remove('show'),2200)}function render(){const trip=read();empty.hidden=!!trip;content.hidden=!trip;if(!trip)return;document.getElementById('tripTitle').textContent=trip.title||'Saved safari route';document.getElementById('tripDuration').textContent=`${trip.duration} ${Number(trip.duration)===1?'day':'days'}`;document.getElementById('tripCountries').textContent=`${trip.countries.length} ${trip.countries.length===1?'country':'countries'}`;document.getElementById('tripStartDate').value=trip.startDate||'';document.getElementById('tripStartSummary').textContent=trip.startDate?`Starts ${new Date(`${trip.startDate}T12:00:00`).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'})}`:'Start date not set';document.getElementById('tripNotes').value=trip.notes||'';document.getElementById('tripDays').innerHTML=trip.stops.map(stop=>`<article><span>${esc(stop.days)}</span><div><strong>${esc(stop.name)}</strong><small>${esc(stop.description)}</small><em>${esc(stop.transfer)}</em></div></article>`).join('');document.querySelectorAll('[data-trip-check]').forEach(box=>box.checked=Boolean(trip.checklist?.[box.dataset.tripCheck]));const save=document.getElementById('saveRoute');if(save)save.textContent='♥'}window.addEventListener('safari-trip-changed',render);document.getElementById('tripStartDate').addEventListener('change',event=>{const trip=read();if(!trip)return;trip.startDate=event.target.value;write(trip);render();toast('Journey date saved on this device.')});document.getElementById('tripChecklist').addEventListener('change',event=>{const box=event.target.closest('[data-trip-check]'),trip=read();if(!box||!trip)return;trip.checklist={...(trip.checklist||{}),[box.dataset.tripCheck]:box.checked};write(trip)});document.getElementById('saveTripNotes').addEventListener('click',()=>{const trip=read();if(!trip)return;trip.notes=document.getElementById('tripNotes').value.trim().slice(0,6000);write(trip);toast('Trip details saved on this device.')});document.getElementById('clearTrip').addEventListener('click',()=>{if(!confirm('Remove this saved trip from the device? Journal sightings and saved places will remain.'))return;localStorage.removeItem(KEY);const save=document.getElementById('saveRoute');if(save)save.textContent='♡';render();toast('Saved trip removed.')});document.getElementById('shareTrip').addEventListener('click',async()=>{const trip=read();if(!trip)return;const itinerary=trip.stops.map(stop=>`${stop.days}: ${stop.name} — ${stop.description}`).join('\n'),text=`${trip.title}\n${trip.duration} days · ${trip.countries.join(', ')}${trip.startDate?` · starts ${trip.startDate}`:''}\n\n${itinerary}\n\nPlanning route only. Confirm bookings, access, transfers and current travel conditions independently.`;try{if(navigator.share)await navigator.share({title:trip.title,text});else{await navigator.clipboard.writeText(text);toast('Trip plan copied.')}}catch(error){if(error.name!=='AbortError')toast('The trip plan could not be shared.')}});render()})();
